            msg = d.get('message', {})
            for c in msg.get('content', []):
                if c.get('type') == 'tool_result':
                    content = c.get('content')
                    if isinstance(content, list):
                        for item in content:
                            if item.get('type')=='text':
                                t = item['text']
                                print('  RESULT:', t[:300].replace(chr(10),' | '))
"

